steps.query:
WITH r AS (
  INSERT INTO replies (ticket_id, author, body) VALUES (12, 'agent', 'Hi, we''ve refunded the duplicate charge on your November invoice. Thanks for your patience.') RETURNING id
), u AS (
  UPDATE tickets SET status = 'closed', updated_at = now() WHERE id = 12 RETURNING id, status
)
SELECT (SELECT id FROM r) AS reply_id, (SELECT status FROM u) AS ticket_status;
